INSERT INTO movies (title, description, duration, genre, release_date, status, poster_url) VALUES
(N'Avatar', N'A paraplegic marine is sent to the moon Pandora and is torn between following orders and protecting the Na''vi people.', 162, N'Sci-Fi', '20091218', N'active', N'Posters/Avatar.webp'),
(N'Avengers: Endgame', N'The surviving Avengers assemble once more to undo the damage caused by Thanos.', 181, N'Action', '20190426', N'active', N'Posters/Avengers_Endgame.webp'),
(N'Deadpool & Wolverine', N'Deadpool is pulled into a multiverse mission and must team up with a reluctant Wolverine.', 128, N'Action', '20240726', N'active', N'Posters/Deadpool_Wolverine.webp'),
(N'Digger', N'A wealthy tycoon scrambles to convince the world he is its savior while a catastrophe he set in motion threatens everything.', 129, N'Comedy', '20261002', N'active', N'Posters/Digger.webp'),
(N'Everything Everywhere All at Once', N'A laundromat owner is swept into a multiverse adventure where she alone can save reality.', 139, N'Sci-Fi', '20220325', N'active', N'Posters/Everything Everywhere_All_at_Once.webp'),
(N'Finding Nemo', N'An overprotective clownfish crosses the ocean to rescue his son with the help of a forgetful blue tang.', 100, N'Animation', '20030530', N'active', N'Posters/Finding_Nemo.webp'),
(N'Forrest Gump', N'A kind-hearted man with a low IQ unwittingly takes part in several defining events of American history.', 142, N'Drama', '19940706', N'active', N'Posters/Forrest_Gump.webp'),
(N'Frozen', N'A fearless princess sets out to find her sister, whose icy powers have trapped their kingdom in eternal winter.', 102, N'Animation', '20131127', N'active', N'Posters/Frozen.webp'),
(N'Godzilla', N'Humanity faces ancient giant monsters as Godzilla rises to restore the balance of nature.', 123, N'Action', '20140516', N'active', N'Posters/Godzilla.webp'),
(N'Harry Potter and the Philosopher''s Stone', N'An orphaned boy discovers he is a wizard and begins his first year at Hogwarts School of Witchcraft and Wizardry.', 152, N'Fantasy', '20011116', N'active', N'Posters/Harry_Potter_and_the_Philosopher''s_Stone.webp'),
(N'Inception', N'A thief who steals secrets through dreams is offered a chance at redemption by planting an idea in a target''s mind.', 148, N'Sci-Fi', '20100716', N'active', N'Posters/Inception.webp'),
(N'Inside Out', N'The emotions inside a young girl''s mind struggle to guide her through a difficult move to a new city.', 95, N'Animation', '20150619', N'active', N'Posters/Inside_Out.webp'),
(N'Interstellar', N'Explorers travel through a wormhole in search of a new home for humanity as Earth faces collapse.', 169, N'Sci-Fi', '20141107', N'active', N'Posters/Interstellar.webp'),
(N'Joker', N'A struggling comedian in Gotham City descends into madness and becomes a symbol of chaos.', 122, N'Drama', '20191004', N'active', N'Posters/Joker.webp'),
(N'Jurassic Park', N'A theme park of cloned dinosaurs turns deadly when its security systems fail.', 127, N'Sci-Fi', '19930611', N'active', N'Posters/Jurassic_Park.webp'),
(N'Mad Max: Fury Road', N'In a desert wasteland, Max joins Furiosa in a high-speed escape from a tyrannical warlord.', 120, N'Action', '20150515', N'active', N'Posters/Mad_Max_Fury_Road.webp'),
(N'The Matrix', N'A hacker learns that reality is a simulation and joins a rebellion against its machine controllers.', 136, N'Sci-Fi', '19990331', N'active', N'Posters/Matrix.webp'),
(N'Parasite', N'A poor family schemes its way into the lives of a wealthy household with unexpected consequences.', 132, N'Thriller', '20190530', N'active', N'Posters/Parasite.webp'),
(N'Skyfall', N'Bond''s loyalty to M is tested when her past comes back to haunt MI6.', 143, N'Action', '20121026', N'active', N'Posters/Skyfall.webp'),
(N'Spirited Away', N'A young girl wanders into a world of spirits and must work in a bathhouse to free her parents.', 125, N'Animation', '20010720', N'active', N'Posters/Spirited_Away.webp'),
(N'Star Wars', N'A farm boy joins a rebel alliance to rescue a princess and stop the Empire''s ultimate weapon.', 121, N'Sci-Fi', '19770525', N'active', N'Posters/Star_Wars.jpg'),
(N'The Dark Knight', N'Batman faces the Joker, a criminal mastermind who pushes Gotham to the edge.', 152, N'Action', '20080718', N'active', N'Posters/The_Dark_Knight.webp'),
(N'The Godfather', N'The aging patriarch of a crime dynasty transfers control of his empire to his reluctant son.', 175, N'Drama', '19720324', N'active', N'Posters/The_Godfather.webp'),
(N'The Hunger Games', N'A teenager volunteers to take her sister''s place in a televised fight to the death.', 142, N'Sci-Fi', '20120323', N'active', N'Posters/The_Hunger_Games.webp'),
(N'The Lion King', N'A young lion prince flees his kingdom after his father''s death, then returns to claim his place.', 88, N'Animation', '19940624', N'active', N'Posters/The_Lion_King.webp'),
(N'The Lord of the Rings: The Fellowship of the Ring', N'A hobbit and a fellowship of allies set out to destroy the One Ring and defeat the Dark Lord Sauron.', 178, N'Fantasy', '20011219', N'active', N'Posters/The_Lord_of_the_Ring_The_Fellowship_of_the_Ring.webp'),
(N'The Shawshank Redemption', N'Two imprisoned men bond over the years, finding solace and eventual redemption through acts of decency.', 142, N'Drama', '19940923', N'active', N'Posters/The_Shawshank_Redemption.webp'),
(N'Titanic', N'A young aristocrat and a penniless artist fall in love aboard the ill-fated RMS Titanic.', 194, N'Romance', '19971219', N'active', N'Posters/Titanic.webp'),
(N'Toy Story', N'A cowboy doll feels threatened when a new space ranger toy becomes his owner''s favorite.', 81, N'Animation', '19951122', N'active', N'Posters/Toy_Story.webp'),
(N'Up', N'An elderly widower ties thousands of balloons to his house and sets off for South America with an unexpected stowaway.', 96, N'Animation', '20090529', N'active', N'Posters/Up.webp');

